struct Customer: Identifiable, Equatable {
    let id: CustomerId                 // stable identity, survives copies
    var name: String

    static func == (lhs: Self, rhs: Self) -> Bool { lhs.id == rhs.id }

    func renamed(_ newName: String) -> Self {      // change produces a new value
        Customer(id: id, name: newName)
    }
}
